 SELECT u::uuid,r::uuid,'20000000-0000-4000-8000-000000000013'::uuid FROM (VALUES
 ('20000000-0000-4000-8000-000000000011','35000000-0000-4000-8000-000000000034'),
 ('20000000-0000-4000-8000-000000000012','35000000-0000-4000-8000-000000000034'),
 ('35000000-0000-4000-8000-000000000011','35000000-0000-4000-8000-000000000031'),
 ('35000000-0000-4000-8000-000000000012','35000000-0000-4000-8000-000000000031'),
 ('35000000-0000-4000-8000-000000000013','35000000-0000-4000-8000-000000000032'),
 ('35000000-0000-4000-8000-000000000014','35000000-0000-4000-8000-000000000033')) AS x(u,r)
 WHERE NOT EXISTS(SELECT 1 FROM ms.user_role_grants g WHERE g.user_id=u::uuid AND g.role_id=r::uuid);
